    for seq in seqs:
        if seq[0] == 0:
            # all 0
            output.append('+'.join(map(str,seq)))
        else:
            # if prod >= 2*n, using addition is never optimal
            prod = 1
            for i in seq:
                prod *= i
                if prod >= 2 * n:
                    break
            if prod >= 2 * n:
                new_seq = ''
                l = 0
                r = len(seq) - 1
                for i in range(len(seq)):
                    if seq[i] != 1:
                        l = i
